// FLASHCARDS + LEITNER
let flashDeck=[],flashIdx=0;
function boxFor(k,stu){return STATE.leitner[k+'_'+stu]||1;}
const BOX_DAYS=[0,1,3,7,16,30]; // dias até rever conforme a caixa
function dueCards(matId,stu,mode){
  const m=DADOS.materias.find(x=>x.id===matId);
  let arr=m.cards.map((c,i)=>({q:c[0],a:c[1],k:'c_'+matId+'_'+i}));
  const now=Date.now();
  if(mode==='due'){
    arr=arr.filter(c=>{
      const L=STATE.leitner[c.k+'_'+stu];
      if(!L)return true; // nunca visto -> due
      const ts=STATE.leitner[c.k+'_'+stu+'_ts']||0;
      const wait=BOX_DAYS[Math.min(L,5)]*864e5;
      return now-ts>=wait;
    });
    if(arr.length===0)arr=m.cards.map((c,i)=>({q:c[0],a:c[1],k:'c_'+matId+'_'+i})); // fallback
  }else if(mode==='hard'){
    arr=arr.filter(c=>boxFor(c.k,stu)<=1);
  }
  return arr;
}
function renderFlashSetup(){
  const sel=document.getElementById('flashMat');const cargo=STATE.stu==='A'?STATE.cargoA:STATE.cargoB;
  sel.innerHTML=matForCargo(cargo).map(m=>`<option value="${m.id}">${m.nome}</option>`).join('');
  sel.onchange=()=>buildDeck(sel.value);buildDeck(matForCargo(cargo)[0].id);
}
function buildDeck(matId){
  const stu=STATE.stu;flashDeck=dueCards(matId,stu,document.getElementById('flashMode').value);
  if(flashDeck.length===0)flashDeck=dueCards(matId,stu,'all');
  flashIdx=0;showCard();
}
document.getElementById('flashMode').onchange=()=>buildDeck(document.getElementById('flashMat').value);
function touchStreak(stu){const t=today();if(STATE.lastDay[stu]!==t){if(STATE.lastDay[stu]){const d=(Date.now()-new Date(STATE.lastDay[stu]).getTime())/864e5;STATE.streak[stu]=(d<=1.5?(STATE.streak[stu]||0)+1:1);}else STATE.streak[stu]=1;STATE.lastDay[stu]=t;save();}}
function showCard(){
  const flip=document.getElementById('flip');flip.classList.remove('flipped');
  const c=flashDeck[flashIdx];if(!c){document.getElementById('fq').textContent='🎉 Tudo revisado por enquanto!';document.getElementById('fa').textContent='Volte depois ou mude o filtro.';document.getElementById('flashCount').textContent='0/0';document.getElementById('leitnerTag').textContent='-';return;}
  document.getElementById('fq').textContent=c.q;document.getElementById('fa').textContent=c.a;
  document.getElementById('flashCount').textContent=`${flashIdx+1} / ${flashDeck.length}`;
  document.getElementById('leitnerTag').textContent='C'+boxFor(c.k,STATE.stu);
}
document.getElementById('flip').onclick=()=>document.getElementById('flip').classList.toggle('flipped');
document.getElementById('prevCard').onclick=()=>{if(flashIdx>0){flashIdx--;showCard();}};
document.getElementById('nextCard').onclick=()=>{if(flashIdx<flashDeck.length-1){flashIdx++;showCard();}};
function markFlash(stu,known){
  const c=flashDeck[flashIdx];if(!c)return;const k=c.k;const L=boxFor(k,stu);
  if(known){STATE.cards[k+'_'+stu]='known';STATE.leitner[k+'_'+stu]=Math.min(L+1,5);}
  else{STATE.cards[k+'_'+stu]='unknown';STATE.leitner[k+'_'+stu]=1;}
  STATE.leitner[k+'_'+stu+'_ts']=Date.now();
  if(known)STATE.xp[stu]=(STATE.xp[stu]||0)+10; else STATE.xp[stu]=(STATE.xp[stu]||0)+2;
  touchStreak(stu);save();checkBadges(stu);
}
document.getElementById('okA').onclick=()=>markFlash('A',true);
document.getElementById('okB').onclick=()=>markFlash('B',true);
document.getElementById('notA').onclick=()=>markFlash('A',false);
document.getElementById('notB').onclick=()=>markFlash('B',false);document.getElementById('sureA').onclick=()=>{STATE.xp.A=(STATE.xp.A||0)+5;STATE.conf['c_'+'A']=(STATE.conf['c_'+'A']||0)+1;save();checkBadges('A');markFlash('A',true);};
document.getElementById('sureB').onclick=()=>{STATE.xp.B=(STATE.xp.B||0)+5;STATE.conf['c_'+'B']=(STATE.conf['c_'+'B']||0)+1;save();checkBadges('B');markFlash('B',true);};


