document.getElementById('startQuiz').onclick=()=>{
  const mode=document.getElementById('quizMode').value;
  let pool=[];
  if(mode==='mixed'){
    const cargo=STATE.stu==='A'?STATE.cargoA:STATE.cargoB;
    matForCargo(cargo).forEach(m=>{m.cards.forEach((c,i)=>pool.push({q:c[0],a:c[1],k:'c_'+m.id+'_'+i,matId:m.id}));});
  }else{
    const m=DADOS.materias.find(x=>x.id===document.getElementById('quizMat').value);
    pool=m.cards.map((c,i)=>({q:c[0],a:c[1],k:'c_'+m.id+'_'+i,matId:m.id}));
  }
  if(mode==='hard'){
    const stu=STATE.stu;pool=pool.filter(c=>boxFor(c.k,stu)<=1);
    if(pool.length===0)pool=m.cards.map((c,i)=>({q:c[0],a:c[1],k:'c_'+m.id+'_'+i,matId:m.id}));
  }
  quizDeck=pool.sort(()=>Math.random()-0.5).slice(0,Math.min(10,pool.length));
  quizIdx=0;quizScore=0;quizLog=[];showQuiz();
};

// PROVA COMPLETA (caderno oficial por cargo + cronometro 4h)
let examTimer=null,examLeft=4*3600,examRun=false;
// pesos oficiais por area tratados em finishQuiz
function examTimeStr(){const h=Math.floor(examLeft/3600),m=Math.floor((examLeft%3600)/60),ss=examLeft%60;return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(ss).padStart(2,'0')}`;}
function startExam(){
  const cargo=STATE.stu==='A'?STATE.cargoA:STATE.cargoB;
  const isMed=['tec'].includes(cargo);
  const mats=matForCargo(cargo);
  const gMats=mats.filter(m=>m.area==='Conhecimentos Gerais');
  const eMats=mats.filter(m=>m.area==='Conhecimentos Específicos');
  const nG=30, nE=isMed?40:50;
  const gPool=[].concat(...gMats.map(m=>m.cards.map((c,i)=>({q:c[0],a:c[1],k:'c_'+m.id+'_'+i,matId:m.id})))).sort(()=>Math.random()-0.5);
  const ePool=[].concat(...eMats.map(m=>m.cards.map((c,i)=>({q:c[0],a:c[1],k:'c_'+m.id+'_'+i,matId:m.id})))).sort(()=>Math.random()-0.5);
  const exDeck=gPool.slice(0,nG).concat(ePool.slice(0,nE)).sort(()=>Math.random()-0.5);
  quizDeck=exDeck;quizIdx=0;quizScore=0;quizAnswered=false;quizLog=[];
  examLeft=4*3600;examRun=true;
  if(examTimer)clearInterval(examTimer);
  examTimer=setInterval(()=>{if(examLeft>0){examLeft--;const el=document.getElementById('examClock');if(el)el.textContent=examTimeStr();}else{clearInterval(examTimer);examRun=false;}},1000);
  const aviso=(gPool.length<nG||ePool.length<nE)?`⚠️ Banco com ${gPool.length} gerais / ${ePool.length} específicos (oficial: ${nG}/${nE}). Estudem mais esses cards.`:'';
  showQuiz(true,aviso);
}
function showQuiz(examMode,aviso){
  const q=quizDeck[quizIdx];if(!q){finishQuiz();return;}
  let opts=[q.a];const all=[];DADOS.materias.forEach(m=>m.cards.forEach(c=>{if(c[1]!==q.a)all.push(c[1]);}));
  all.sort(()=>Math.random()-0.5);for(let i=0;i<3&&i<all.length;i++)opts.push(all[i]);opts.sort(()=>Math.random()-0.5);
  const examOn=typeof examMode!=='undefined'&&examMode;
  document.getElementById('quizInfo').innerHTML=`Q ${quizIdx+1}/${quizDeck.length} · Acertos: ${quizScore}`+(examOn?` · ⏱️ <b id="examClock">${examTimeStr()}</b>`:'');
  let html=`<div class="quiz-q"><div class="q-tag" style="font-size:12px;color:var(--muted);font-weight:700;margin-bottom:8px">${DADOS.materias.find(x=>x.id===q.matId).nome}</div>
    <div class="q" style="font-size:16px;font-weight:700;margin-bottom:14px">${q.q}</div>`;
  opts.forEach(o=>html+=`<button class="quiz-opt" data-o="${o.replace(/"/g,'&quot;')}">${o}</button>`);
  html+=`<div class="feedback" id="fb" style="display:none"></div><div class="btn-row" style="margin-top:14px"><button class="btn primary" id="nextQuiz">Próxima ⟶</button></div></div>`;
  let av=(aviso)?`<div class="note" style="margin-bottom:12px">${aviso}</div>`:'';
  document.getElementById('quizBox').innerHTML=av+html;quizAnswered=false;
  document.querySelectorAll('.quiz-opt').forEach(btn=>{btn.onclick=()=>{
    if(quizAnswered)return;quizAnswered=true;const correct=(btn.dataset.o===q.a);
    document.querySelectorAll('.quiz-opt').forEach(b=>{if(b.dataset.o===q.a)b.classList.add('correct');else if(b===btn)b.classList.add('wrong');else b.classList.add('dim');});
    const fb=document.getElementById('fb');fb.style.display='block';
    fb.innerHTML=correct?`✅ <b>Correto!</b> ${q.a}`:`❌ <b>Errado.</b> ${q.a}`;
    if(correct)quizScore++;quizLog.push({matId:q.matId,correct});const stu=STATE.stu;
    STATE.cards[q.k+'_'+stu]='known';STATE.leitner[q.k+'_'+stu+'_ts']=Date.now();
    STATE.leitner[q.k+'_'+stu]=Math.min((boxFor(q.k,stu)+1),5);
    if(correct)STATE.xp[stu]=(STATE.xp[stu]||0)+15; else STATE.xp[stu]=(STATE.xp[stu]||0)+3;
    touchStreak(stu);save();checkBadges(stu);
    document.getElementById('nextQuiz').onclick=()=>{quizIdx++;showQuiz();};
  };});
}
function finishQuiz(){
  if(examTimer){clearInterval(examTimer);examRun=false;}
  document.getElementById('quizInfo').textContent='';
  const examOn=quizDeck.length>=30;
  let html=`<div class="quiz-q"><h3 style="color:var(--navy);font-size:20px;text-align:center">Concluído! 🎉</h3><p style="font-size:18px;margin:14px 0;text-align:center">${STATE.stu} acertou <b>${quizScore}</b> de <b>${quizDeck.length}</b>.</p>`;
  if(examOn){
    const agg={};quizLog.forEach(r=>{if(!agg[r.matId])agg[r.matId]={t:0,a:0};agg[r.matId].t++;if(r.correct)agg[r.matId].a++;});
    html+='<div class="card" style="margin-top:10px"><h3>📊 Desempenho por matéria</h3>';
    Object.entries(agg).forEach(([mid,d])=>{const m=DADOS.materias.find(x=>x.id===mid);const p=Math.round(d.a/d.t*100);const w=m.area==='Conhecimentos Específicos'?(STATE.stu==='A'&&['tec'].includes(STATE.cargoA)?'1,60':'1,28'):'1,20';html+=`<div class="stat-row"><span>${m.nome}</span><span>${d.a}/${d.t} (${p}%) · peso ${w}</span></div><div class="bar"><i style="width:${p}%"></i></div>`;});
    html+='</div><p class="sub" style="text-align:center;margin-top:10px">Dica: foque nas matérias com menor % de acerto nos próximos dias.</p>';
  }
  html+='<div class="btn-row" style="justify-content:center;margin-top:14px"><button class="btn green" onclick="document.getElementById(\'startQuiz\').click()">🔁 Refazer</button></div></div>';
  document.getElementById('quizBox').innerHTML=html;
}

