function packShare(){
  const payload={t:STATE.topics,c:STATE.cards,l:STATE.leitner,st:STATE.streak,ld:STATE.lastDay,cy:STATE.pomoCycles,xp:STATE.xp,bg:STATE.badges,cf:STATE.conf};
  return 'https://leonardolauriquer.github.io/estuda-palhoca/#d='+btoa(unescape(encodeURIComponent(JSON.stringify(payload))));
}
document.getElementById('genLink').onclick=()=>{document.getElementById('shareOut').value=packShare();};
document.getElementById('copyLink').onclick=()=>{const o=document.getElementById('shareOut');o.select();document.execCommand('copy');
  document.getElementById('copyLink').textContent='✅ Copiado!';setTimeout(()=>document.getElementById('copyLink').textContent='📋 Copiar',1500);};
document.getElementById('mergeBtn').onclick=()=>{
  const raw=document.getElementById('shareIn').value.trim();const mm=raw.match(/#d=([^&\s]+)/);if(!mm){document.getElementById('mergeMsg').textContent='❌ Link inválido.';return;}
  try{
    const inc=JSON.parse(decodeURIComponent(escape(atob(mm[1]))));
    let n=0;
    const merge=(recv,cur)=>{for(const k in recv){if(recv[k]&&recv[k]!=='unknown'){if(!(k in cur)||cur[k]==='unknown'||recv[k]==='known'){cur[k]=recv[k];n++;}}}};
    merge(inc.t,STATE.topics);merge(inc.c,STATE.cards);merge(inc.l,STATE.leitner);
    for(const k in inc.st)STATE.streak[k]=Math.max(STATE.streak[k]||0,inc.st[k]||0);
    for(const k in inc.ld)if(!STATE.lastDay[k]||inc.ld[k]>STATE.lastDay[k])STATE.lastDay[k]=inc.ld[k];
    STATE.pomoCycles=Math.max(STATE.pomoCycles||0,inc.cy||0);
    if(inc.xp)for(const k in inc.xp)STATE.xp[k]=Math.max(STATE.xp[k]||0,inc.xp[k]||0);
    if(inc.bg)for(const k in inc.bg)STATE.badges[k]=(STATE.badges[k]||[]).concat(inc.bg[k]||[]).filter((v,i,a)=>a.indexOf(v)===i);
    if(inc.conf)for(const k in inc.conf)STATE.conf[k]=(STATE.conf[k]||0)+(inc.conf[k]||0);
    save();document.getElementById('mergeMsg').textContent=`✅ Unidos! ${n} itens atualizados.`;renderDash();
  }catch(e){document.getElementById('mergeMsg').textContent='❌ Erro ao ler.';}
};
