let pomoTimer=null,pomoTleft=25*60,pomoMode='Foco',pomoRun=false;
function pomoRender(){const m=Math.floor(pomoTleft/60),s=pomoTleft%60;
  document.getElementById('pomoClock').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;
  document.getElementById('pomoMode').textContent=`${pomoMode.toUpperCase()} · ${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;}
document.getElementById('pomoStart').onclick=()=>{if(pomoRun){clearInterval(pomoTimer);pomoRun=false;document.getElementById('pomoStart').textContent='▶️ Iniciar';return;}
  pomoRun=true;document.getElementById('pomoStart').textContent='⏸️ Pausar';
  pomoTimer=setInterval(()=>{if(pomoTleft>0){pomoTleft--;pomoRender();}else{clearInterval(pomoTimer);pomoRun=false;
    if(pomoMode==='Foco'){STATE.pomoCycles++;touchStreak(STATE.stu);save();document.getElementById('pomoCycles').textContent=STATE.pomoCycles;pomoMode='Pausa';pomoTleft=5*60;}else{pomoMode='Foco';pomoTleft=25*60;}
    document.getElementById('pomoStart').textContent='▶️ Iniciar';pomoRender();}},1000);};
document.getElementById('pomoReset').onclick=()=>{clearInterval(pomoTimer);pomoRun=false;pomoMode='Foco';pomoTleft=25*60;document.getElementById('pomoStart').textContent='▶️ Iniciar';pomoRender();};
document.getElementById('pomoCycles').textContent=STATE.pomoCycles;

// SOBRE


function xpForLevel(xp){let lvl=1,need=100;while(xp>=need){xp-=need;lvl++;need=Math.round(need*1.35);}return {lvl,cur:xp,need};}
function masteryPct(cargo,stu){
  const mats=matForCargo(cargo);let dom=0,tot=0;
  mats.forEach(m=>{m.cards.forEach((_,i)=>{const k='c_'+m.id+'_'+i+'_'+stu;tot++;if(STATE.cards[k]==='known'&&(STATE.leitner[k]||1)>=5)dom++;});});
  return tot?Math.round(dom/tot*100):0;
}
function checkBadges(stu){
  const xp=STATE.xp[stu]||0;const b=STATE.badges[stu]||(STATE.badges[stu]=[]);
  const add=(id,nm)=>{if(!b.includes(id)){b.push(id);}};
  if(xp>=100)add('b1','Iniciante 🥉');
  if(xp>=300)add('b2','Veterano 🥈');
  if(xp>=700)add('b3','Mestre 🥇');
  if((STATE.streak[stu]||0)>=7)add('b4','Sequência 7d 🔥');
  if(masteryPct(stu==='A'?STATE.cargoA:STATE.cargoB,stu)>=50)add('b5','Meio caminho 🎯');
  if(masteryPct(stu==='A'?STATE.cargoA:STATE.cargoB,stu)>=90)add('b6','Quase lá 🏆');
}
function renderTrophy(){
  const stu=STATE.stu;
  const lvA=xpForLevel(STATE.xp.A||0),lvB=xpForLevel(STATE.xp.B||0);
  let html='<div class="rank-card">';
  const player=(who,lv,xp)=>`<div class="player ${who}"><div class="lvl">Nv ${lv.lvl}</div><div class="nm">${who==='A'?'Você (A)':'Amiga (B)'}</div><div class="xp">⭐ ${xp} XP</div><div class="xpbar"><i style="width:${Math.round(lv.cur/lv.need*100)}%"></i></div><div style="margin-top:8px">${(STATE.badges[who]||[]).map(b=>'<span class="badge-pill">'+b+'</span>').join('')||'<span style="font-size:11px;color:var(--muted)">sem medalhas ainda</span>'}</div></div>`;
  html+=player('A',lvA,STATE.xp.A||0)+player('B',lvB,STATE.xp.B||0);
  html+='</div>';
  // Duelo do dia
  const a=STATE.xp.A||0,b=STATE.xp.B||0;
  let winner = a===b?'🤝 Empate hoje!':(a>b?'🥇 Você (A) vai na frente!':'🥇 Amiga (B) vai na frente!');
  html+='<div class="card"><h3>⚔️ Duelo de Pontos (total acumulado)</h3><div class="duel-winner">'+winner+'</div>';
  html+='<div class="stat-row"><span>Você (A)</span><span>'+a+' XP</span></div><div class="bar"><i style="width:'+(a+b?Math.round(a/(a+b)*100):0)+'%"></i></div>';
  html+='<div class="stat-row"><span>Amiga (B)</span><span>'+b+' XP</span></div><div class="bar"><i style="width:'+(a+b?Math.round(b/(a+b)*100):0)+'%"></i></div></div>';
  // Maestria por matéria (do estudante atual)
  const cargo=stu==='A'?STATE.cargoA:STATE.cargoB;
  html+='<div class="card"><h3>🎯 Maestria por matéria — '+(stu==='A'?'Você (A)':'Amiga (B)')+'</h3><div class="mastery">';
  matForCargo(cargo).forEach(m=>{const p=masteryPct(cargo,stu);});
  // per-matter mastery needs per-matter calc
  matForCargo(cargo).forEach(m=>{let dom=0,tot=m.cards.length;m.cards.forEach((_,i)=>{const k='c_'+m.id+'_'+i+'_'+stu;if(STATE.cards[k]==='known'&&(STATE.leitner[k]||1)>=5)dom++;});const p=tot?Math.round(dom/tot*100):0;html+='<div class="ms"><div class="top"><span>'+m.nome+'</span><span class="pct">'+p+'%</span></div><div class="xpbar"><i style="width:'+p+'%"></i></div></div>';});
  html+='</div></div>';
  document.getElementById('trophyBox').innerHTML=html;
}

